mapper.select:
select id, username, password, name, gender, phone, job, salary, image, entry_date as entryDate, create_time as createTime, update_time as updateTime from emp
and name like concat('%', #{name}, '%')
and gender = #{gender}
and entry_date >= #{begin}
and entry_date <= #{end}
order by update_time desc

mapper.update:
update emp
username = #{username}, password = #{password}, name = #{name}, gender = #{gender}, phone = #{phone}, job = #{job}, salary = #{salary}, image = #{image}, entry_date = #{entryDate}, update_time = #{updateTime},
where id = #{id}

update emp
set password = #{password}
where id = #{id}
